//! rstest fixtures for code2prompt integration tests

use super::test_env::*;
use colored::*;
use log::info;
use rstest::*;
use std::fs;

/// Fixture for basic test environment with standard file hierarchy
#[fixture]
pub fn basic_test_env() -> BasicTestEnv {
    let env = BasicTestEnv::new();
    create_standard_hierarchy(env.dir.path());
    env
}

/// Fixture for git test environment with gitignore setup
#[fixture]
pub fn git_test_env() -> GitTestEnv {
    let env = GitTestEnv::new();
    create_git_hierarchy(env.dir.path());
    env
}

/// Fixture for stdout test environment with simple files
#[fixture]
pub fn stdout_test_env() -> StdoutTestEnv {
    let env = StdoutTestEnv::new();
    create_simple_test_files(env.dir.path());
    env
}

/// Fixture for template test environment with code structure
#[fixture]
pub fn template_test_env() -> TemplateTestEnv {
    let env = TemplateTestEnv::new();
    create_test_codebase(env.dir.path());
    env
}

/// Create standard test hierarchy (lowercase/uppercase directories with various files)
pub fn create_standard_hierarchy(base_path: &std::path::Path) {
    let lowercase_dir = base_path.join("lowercase");
    let uppercase_dir = base_path.join("uppercase");

    fs::create_dir_all(&lowercase_dir).unwrap();
    fs::create_dir_all(&uppercase_dir).unwrap();

    let files = vec![
        ("lowercase/foo.py", "content foo.py"),
        ("lowercase/bar.py", "content bar.py"),
        ("lowercase/baz.py", "content baz.py"),
        ("lowercase/qux.txt", "content qux.txt"),
        ("lowercase/corge.txt", "content corge.txt"),
        ("lowercase/grault.txt", "content grault.txt"),
        ("uppercase/FOO.py", "CONTENT FOO.PY"),
        ("uppercase/BAR.py", "CONTENT BAR.PY"),
        ("uppercase/BAZ.py", "CONTENT BAZ.PY"),
        ("uppercase/QUX.txt", "CONTENT QUX.TXT"),
        ("uppercase/CORGE.txt", "CONTENT CORGE.TXT"),
        ("uppercase/GRAULT.txt", "CONTENT GRAULT.TXT"),
    ];

    for (file_path, content) in files {
        create_temp_file(base_path, file_path, content);
    }

    info!(
        "{}{}{} {}",
        "[".bold().white(),
        "✓".bold().green(),
        "]".bold().white(),
        "Standard test hierarchy created".green()
    );
}

/// Create git test hierarchy with gitignore
pub fn create_git_hierarchy(base_path: &std::path::Path) {
    let test_dir = base_path.join("test_dir");
    fs::create_dir_all(&test_dir).unwrap();

    let files = vec![
        ("test_dir/included.txt", "Included file"),
        ("test_dir/ignored.txt", "Ignored file"),
    ];

    for (file_path, content) in files {
        create_temp_file(base_path, file_path, content);
    }

    // Create a .gitignore file
    let gitignore_path = base_path.join(".gitignore");
    let mut gitignore_file =
        std::fs::File::create(&gitignore_path).expect("Failed to create .gitignore file");
    use std::io::Write;
    writeln!(gitignore_file, "test_dir/ignored.txt").expect("Failed to write to .gitignore file");

    info!(
        "{}{}{} {}",
        "[".bold().white(),
        "✓".bold().green(),
        "]".bold().white(),
        "Git test hierarchy created".green()
    );
}

/// Create simple test files for stdout tests
pub fn create_simple_test_files(base_path: &std::path::Path) {
    let files = vec![
        ("test.py", "print('Hello, World!')"),
        ("README.md", "# Test Project\nThis is a test."),
        ("config.json", r#"{"name": "test", "version": "1.0.0"}"#),
    ];

    for (file_path, content) in files {
        create_temp_file(base_path, file_path, content);
    }

    info!(
        "{}{}{} {}",
        "[".bold().white(),
        "✓".bold().green(),
        "]".bold().white(),
        "Simple test files created".green()
    );
}

/// Create test codebase for template tests
pub fn create_test_codebase(base_path: &std::path::Path) {
    let files = vec![
        (
            "src/main.rs",
            "fn main() {\n    println!(\"Hello, world!\");\n}",
        ),
        (
            "src/lib.rs",
            "pub fn add(a: i32, b: i32) -> i32 {\n    a + b\n}",
        ),
        (
            "tests/test.rs",
            "#[test]\nfn test_add() {\n    assert_eq!(3, add(1, 2));\n}",
        ),
    ];

    for (file_path, content) in files {
        create_temp_file(base_path, file_path, content);
    }

    info!(
        "{}{}{} {}",
        "[".bold().white(),
        "✓".bold().green(),
        "]".bold().white(),
        "Test codebase created".green()
    );
}

use code2prompt_core::path::FileEntry;
use std::path::Path;
use code2prompt_core::analysis::{CodebaseAnalysis, TokenMapOptions};
use code2prompt_core::path::EntryMetadata;

#[cfg(test)]
mod tests {
    use super::*;

    fn mock_file(path: &str, tokens: usize, is_dir: bool) -> FileEntry {
        FileEntry {
            path: path.to_string(),
            extension: if is_dir {
                String::new()
            } else {
                Path::new(path)
                    .extension()
                    .and_then(|s| s.to_str())
                    .unwrap_or("")
                    .to_string()
            },
            code: String::new(),
            token_count: tokens,
            metadata: EntryMetadata {
                is_dir,
                is_symlink: false,
            },
            mod_time: None,
            entities: vec![],
        }
    }

    #[test]
    fn test_simple_tree_building() {
        let files = vec![
            mock_file("src/main.rs", 100, false),
            mock_file("src/lib.rs", 200, false),
        ];

        let analysis = CodebaseAnalysis::new(&files, 300);
        let entries = analysis.token_map(TokenMapOptions {
            max_lines: 100,
            min_percent: 0.0,
        });

        // Should have: src (dir), src/main.rs, src/lib.rs
        assert!(entries.len() >= 3, "Expected at least 3 entries, got {}", entries.len());

        // Find the src directory entry
        let src_entry = entries.iter().find(|e| e.name == "src");
        assert!(src_entry.is_some(), "Should have 'src' directory");
        assert_eq!(src_entry.unwrap().tokens, 300, "src should have 300 tokens");
    }

    #[test]
    fn test_nested_directory_structure() {
        let files = vec![
            mock_file("website/public/assets/logo.svg", 100, false),
            mock_file("website/public/favicon.ico", 50, false),
        ];

        let analysis = CodebaseAnalysis::new(&files, 150);
        let entries = analysis.token_map(TokenMapOptions {
            max_lines: 100,
            min_percent: 0.0,
        });

        // Verify hierarchy: website -> public -> assets -> logo.svg
        let website = entries.iter().find(|e| e.name == "website");
        assert!(website.is_some(), "Should have 'website' at root");
        assert_eq!(website.unwrap().depth, 0, "website should be at depth 0");

        let public = entries.iter().find(|e| e.name == "public");
        assert!(public.is_some(), "Should have 'public'");
        assert_eq!(public.unwrap().depth, 1, "public should be at depth 1");

        let assets = entries.iter().find(|e| e.name == "assets");
        assert!(assets.is_some(), "Should have 'assets'");
        assert_eq!(assets.unwrap().depth, 2, "assets should be at depth 2");

        let logo = entries.iter().find(|e| e.name == "logo.svg");
        assert!(logo.is_some(), "Should have 'logo.svg'");
        assert_eq!(logo.unwrap().depth, 3, "logo.svg should be at depth 3");
    }

    #[test]
    fn test_token_accumulation() {
        let files = vec![
            mock_file("src/a.rs", 100, false),
            mock_file("src/b.rs", 200, false),
            mock_file("src/sub/c.rs", 50, false),
        ];

        let analysis = CodebaseAnalysis::new(&files, 350);
        let entries = analysis.token_map(TokenMapOptions {
            max_lines: 100,
            min_percent: 0.0,
        });

        let src = entries.iter().find(|e| e.name == "src");
        assert!(src.is_some());
        assert_eq!(src.unwrap().tokens, 350, "src should accumulate all tokens");

        let sub = entries.iter().find(|e| e.name == "sub");
        assert!(sub.is_some());
        assert_eq!(sub.unwrap().tokens, 50, "sub should have 50 tokens");
    }

    #[test]
    fn test_by_extension() {
        let files = vec![
            mock_file("a.rs", 100, false),
            mock_file("b.rs", 200, false),
            mock_file("c.js", 50, false),
            mock_file("d.js", 75, false),
        ];

        let analysis = CodebaseAnalysis::new(&files, 425);
        let ext_stats = analysis.by_extension();

        assert_eq!(ext_stats.len(), 2, "Should have 2 extensions");

        // Should be sorted by tokens descending
        assert_eq!(ext_stats[0].extension, "rs");
        assert_eq!(ext_stats[0].tokens, 300);
        assert_eq!(ext_stats[0].file_count, 2);

        assert_eq!(ext_stats[1].extension, "js");
        assert_eq!(ext_stats[1].tokens, 125);
        assert_eq!(ext_stats[1].file_count, 2);
    }

    #[test]
    fn test_filtering_by_max_lines() {
        let files = vec![
            mock_file("a.rs", 1000, false),
            mock_file("b.rs", 500, false),
            mock_file("c.rs", 200, false),
            mock_file("d.rs", 100, false),
        ];

        let analysis = CodebaseAnalysis::new(&files, 1800);
        let entries = analysis.token_map(TokenMapOptions {
            max_lines: 2, // Only show top 2
            min_percent: 0.0,
        });

        // Should have top 2 files + possibly "other files"
        let file_entries: Vec<_> = entries.iter().filter(|e| !e.metadata.is_dir).collect();
        assert!(file_entries.len() <= 3, "Should have at most 3 file entries (2 + other)");
    }

    #[test]
    fn test_filtering_by_min_percent() {
        let files = vec![
            mock_file("big.rs", 900, false),
            mock_file("small.rs", 50, false), // Only 5.5% - should be filtered
        ];

        let analysis = CodebaseAnalysis::new(&files, 950);
        let entries = analysis.token_map(TokenMapOptions {
            max_lines: 100,
            min_percent: 10.0, // 10% minimum
        });

        let big = entries.iter().find(|e| e.name == "big.rs");
        assert!(big.is_some(), "big.rs should be included");

        let small = entries.iter().find(|e| e.name == "small.rs");
        assert!(small.is_none(), "small.rs should be filtered out");
    }

    #[test]
    fn test_realistic_project_structure() {
        let files = vec![
            mock_file("crates/code2prompt/src/main.rs", 5000, false),
            mock_file("crates/code2prompt/src/args.rs", 3000, false),
            mock_file("crates/code2prompt-core/src/analysis.rs", 2000, false),
            mock_file("website/src/index.html", 1000, false),
            mock_file("website/public/favicon.ico", 500, false),
            mock_file("README.md", 200, false),
        ];

        let total = files.iter().map(|f| f.token_count).sum();
        let analysis = CodebaseAnalysis::new(&files, total);

        // Test with permissive settings
        let entries = analysis.token_map(TokenMapOptions {
            max_lines: 50,
            min_percent: 0.0,
        });

        println!("\n=== Token Map Entries ===");
        for entry in &entries {
            println!("Depth {}: {} ({} tokens, {}%)", 
                entry.depth, entry.name, entry.tokens, entry.percentage);
        }

        // Should have the directory structure
        assert!(!entries.is_empty(), "Should have entries");

        // Check that we have the crates directory
        let crates_dir = entries.iter().find(|e| e.name == "crates");
        assert!(crates_dir.is_some(), "Should have 'crates' directory");

        // Check that we have nested structure
        let has_depth_2 = entries.iter().any(|e| e.depth >= 2);
        assert!(has_depth_2, "Should have nested structure with depth >= 2");
    }
}

//! Tests for binary file detection using content_inspector

use code2prompt_core::configuration::Code2PromptConfig;
use code2prompt_core::path::traverse_directory;
use std::fs;
use tempfile::TempDir;

/// Helper to create a test directory with mixed binary and text files
fn create_test_directory_with_binary() -> TempDir {
    let temp_dir = TempDir::new().unwrap();
    let base_path = temp_dir.path();

    // Create text files
    fs::write(base_path.join("text.txt"), "This is a text file").unwrap();
    fs::write(
        base_path.join("code.rs"),
        "fn main() { println!(\"Hello\"); }",
    )
    .unwrap();
    fs::write(base_path.join("data.json"), r#"{"key": "value"}"#).unwrap();

    // Create text file with non-UTF8 encoding (GB2312)
    let mut gb2312_data = b"GB2312 test: ".to_vec();
    // Append "你好" encoded in GB2312
    // '你' is 0xC4 0xE3
    // '好' is 0xBA 0xC3
    gb2312_data.extend_from_slice(&[0xC4, 0xE3, 0xBA, 0xC3]);
    fs::write(base_path.join("chinese_gb2312.txt"), gb2312_data).unwrap();

    // Create binary files (simulated)
    // PNG header signature
    let mut png_data = vec![0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
    // Append some zeros and random high bytes to ensure it hits the binary heuristic
    png_data.extend_from_slice(&[0x00, 0x00, 0x00, 0xFF, 0xFE]);
    fs::write(base_path.join("image.png"), png_data).unwrap();

    // Random binary data
    let binary_data: Vec<u8> = (0..100).map(|i| (i * 7) as u8).collect();
    fs::write(base_path.join("binary.bin"), binary_data).unwrap();

    // JPEG header
    let mut jpeg_data = vec![0xFF, 0xD8, 0xFF, 0xE0];
    jpeg_data.extend_from_slice(&[0x00, 0x10, 0x4A, 0x46, 0x49, 0x46, 0x00]);
    fs::write(base_path.join("photo.jpg"), jpeg_data).unwrap();

    // Compiled object file simulation (ELF header with more data)
    let mut elf_data = vec![0x7F, b'E', b'L', b'F']; // ELF magic
    // Add more binary data to make it clearly binary
    elf_data.extend_from_slice(&[0x02, 0x01, 0x01, 0x00]); // 64-bit, little endian, etc
    elf_data.extend((0..50).map(|i| (i * 13) as u8)); // More binary content
    fs::write(base_path.join("compiled.o"), elf_data).unwrap();

    temp_dir
}

#[test]
fn test_binary_files_are_skipped() {
    let temp_dir = create_test_directory_with_binary();
    let config = Code2PromptConfig::builder()
        .path(temp_dir.path().to_path_buf())
        .build()
        .unwrap();

    let (_, files) = traverse_directory(&config, None).unwrap();

    // Should only include text files, not binary files
    let file_paths: Vec<String> = files.iter().map(|f| f.path.clone()).collect();

    // Text files should be included
    assert!(file_paths.iter().any(|p| p.contains("text.txt")));
    assert!(file_paths.iter().any(|p| p.contains("code.rs")));
    assert!(file_paths.iter().any(|p| p.contains("data.json")));
    assert!(file_paths.iter().any(|p| p.contains("chinese_gb2312.txt")));

    // Binary files should be excluded
    assert!(!file_paths.iter().any(|p| p.contains("image.png")));
    assert!(!file_paths.iter().any(|p| p.contains("binary.bin")));
    assert!(!file_paths.iter().any(|p| p.contains("photo.jpg")));
    assert!(!file_paths.iter().any(|p| p.contains("compiled.o")));

    // Should have exactly 3 text files
    assert_eq!(files.len(), 4);
}

#[test]
fn test_empty_file_handling() {
    let temp_dir = TempDir::new().unwrap();
    let base_path = temp_dir.path();

    // Create an empty file
    fs::write(base_path.join("empty.txt"), "").unwrap();

    let config = Code2PromptConfig::builder()
        .path(base_path.to_path_buf())
        .build()
        .unwrap();

    let (_, files) = traverse_directory(&config, None).unwrap();

    // Empty files should be excluded (existing behavior)
    assert_eq!(files.len(), 0);
}

#[test]
fn test_small_binary_file() {
    let temp_dir = TempDir::new().unwrap();
    let base_path = temp_dir.path();

    // Create a very small binary file (less than 8KB)
    let small_binary: Vec<u8> = vec![0x00, 0xFF, 0x00, 0xFF, 0xFE, 0xED];
    fs::write(base_path.join("small.bin"), small_binary).unwrap();

    let config = Code2PromptConfig::builder()
        .path(base_path.to_path_buf())
        .build()
        .unwrap();

    let (_, files) = traverse_directory(&config, None).unwrap();

    // Small binary file should still be detected and excluded
    assert_eq!(files.len(), 0);
}

#[test]
fn test_text_file_with_unicode() {
    let temp_dir = TempDir::new().unwrap();
    let base_path = temp_dir.path();

    // Create text file with Unicode characters
    fs::write(
        base_path.join("unicode.txt"),
        "Hello 世界 🌍 Здравствуй мир",
    )
    .unwrap();

    let config = Code2PromptConfig::builder()
        .path(base_path.to_path_buf())
        .build()
        .unwrap();

    let (_, files) = traverse_directory(&config, None).unwrap();

    // Unicode text should be detected as text and included
    assert_eq!(files.len(), 1);
    let file_path = &files[0].path;
    assert!(file_path.contains("unicode.txt"));
}

#[test]
fn test_mixed_directory_structure() {
    let temp_dir = TempDir::new().unwrap();
    let base_path = temp_dir.path();

    // Create nested structure with mixed files
    fs::create_dir(base_path.join("src")).unwrap();
    fs::create_dir(base_path.join("assets")).unwrap();

    // Text files in src/
    fs::write(base_path.join("src/main.rs"), "fn main() {}").unwrap();
    fs::write(base_path.join("src/lib.rs"), "pub mod test {}").unwrap();

    // Binary files in assets/
    let png_data = vec![0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
    fs::write(base_path.join("assets/logo.png"), png_data).unwrap();

    let config = Code2PromptConfig::builder()
        .path(base_path.to_path_buf())
        .build()
        .unwrap();

    let (_, files) = traverse_directory(&config, None).unwrap();

    // Should only have 2 text files from src/
    assert_eq!(files.len(), 2);

    let file_paths: Vec<String> = files.iter().map(|f| f.path.clone()).collect();

    assert!(file_paths.iter().any(|p| p.contains("main.rs")));
    assert!(file_paths.iter().any(|p| p.contains("lib.rs")));
    assert!(!file_paths.iter().any(|p| p.contains("logo.png")));
}

#[test]
fn test_large_text_file() {
    let temp_dir = TempDir::new().unwrap();
    let base_path = temp_dir.path();

    // Create a large text file (> 8KB) to test that full file is read after sample
    let large_text = "Lorem ipsum dolor sit amet. ".repeat(1000); // ~28KB
    fs::write(base_path.join("large.txt"), &large_text).unwrap();

    let config = Code2PromptConfig::builder()
        .path(base_path.to_path_buf())
        .build()
        .unwrap();

    let (_, files) = traverse_directory(&config, None).unwrap();

    // Large text file should be detected and included
    assert_eq!(files.len(), 1);

    // Verify the entire content was read (not just the sample)
    let code = &files[0].code;
    assert!(code.contains(&large_text));
}

#[test]
fn test_pdf_detection() {
    let temp_dir = TempDir::new().unwrap();
    let base_path = temp_dir.path();

    // PDF file header
    let pdf_header = b"%PDF-1.4\n";
    fs::write(base_path.join("document.pdf"), pdf_header).unwrap();

    let config = Code2PromptConfig::builder()
        .path(base_path.to_path_buf())
        .build()
        .unwrap();

    let (_, files) = traverse_directory(&config, None).unwrap();

    // PDF should be detected as binary and excluded
    assert_eq!(files.len(), 0);
}

#[test]
fn test_various_text_formats() {
    let temp_dir = TempDir::new().unwrap();
    let base_path = temp_dir.path();

    // Various text file formats
    fs::write(base_path.join("config.yaml"), "key: value\n").unwrap();
    fs::write(base_path.join("data.xml"), "<root><item/></root>").unwrap();
    fs::write(base_path.join("script.sh"), "#!/bin/bash\necho 'test'").unwrap();
    fs::write(base_path.join("style.css"), "body { margin: 0; }").unwrap();
    fs::write(base_path.join("page.html"), "<html><body></body></html>").unwrap();

    let config = Code2PromptConfig::builder()
        .path(base_path.to_path_buf())
        .build()
        .unwrap();

    let (_, files) = traverse_directory(&config, None).unwrap();

    // All text formats should be included
    assert_eq!(files.len(), 5);
}

//! Tests for file processor module
//!
//! This file contains all tests for the file processor implementations,
//! organized by processor type.

use code2prompt_core::file_processor::*;
use std::path::PathBuf;

// ============================================================================
// CSV Processor Tests
// ============================================================================

mod csv_tests {
    use super::*;

    #[test]
    fn test_csv_with_headers_and_data() {
        let processor = CsvProcessor;
        let content = b"name,age,city\nAlice,30,NYC\nBob,25,LA\nCharlie,35,SF";
        let result = processor
            .process(content, &PathBuf::from("test.csv"))
            .unwrap();

        assert!(result.contains("Headers: name, age, city"));
        assert!(result.contains("Sample: \"Alice\", \"30\", \"NYC\""));
        assert!(result.contains("[2 more rows omitted]"));
    }

    #[test]
    fn test_csv_with_quoted_fields() {
        let processor = CsvProcessor;
        let content =
            b"name,description\n\"John Doe\",\"Software Engineer, Senior\"\n\"Jane\",\"Manager\"";
        let result = processor
            .process(content, &PathBuf::from("test.csv"))
            .unwrap();

        assert!(result.contains("Headers: name, description"));
        assert!(result.contains("Sample: \"John Doe\", \"Software Engineer, Senior\""));
    }

    #[test]
    fn test_csv_empty() {
        let processor = CsvProcessor;
        let content = b"name,age\n";
        let result = processor
            .process(content, &PathBuf::from("test.csv"))
            .unwrap();

        assert!(result.contains("Headers: name, age"));
        assert!(result.contains("(No data rows found)"));
    }

    #[test]
    fn test_csv_malformed_fallback() {
        let processor = CsvProcessor;
        let content = b"not a valid csv file\nwith random\ncontent";
        let result = processor
            .process(content, &PathBuf::from("test.csv"))
            .unwrap();

        // Should fallback to raw text
        assert!(result.contains("not a valid csv file"));
    }
}

// ============================================================================
// TSV Processor Tests
// ============================================================================

mod tsv_tests {
    use super::*;

    #[test]
    fn test_tsv_with_headers_and_data() {
        let processor = TsvProcessor;
        let content = b"name\tage\tcity\nAlice\t30\tNYC\nBob\t25\tLA\nCharlie\t35\tSF";
        let result = processor
            .process(content, &PathBuf::from("test.tsv"))
            .unwrap();

        assert!(result.contains("TSV Schema"));
        assert!(result.contains("Headers: name, age, city"));
        assert!(result.contains("Sample: \"Alice\", \"30\", \"NYC\""));
        assert!(result.contains("[2 more rows omitted]"));
    }

    #[test]
    fn test_tsv_with_spaces() {
        let processor = TsvProcessor;
        let content = b"name\tdescription\nJohn Doe\tSoftware Engineer\nJane\tManager";
        let result = processor
            .process(content, &PathBuf::from("test.tsv"))
            .unwrap();

        assert!(result.contains("TSV Schema"));
        assert!(result.contains("Headers: name, description"));
        assert!(result.contains("Sample: \"John Doe\", \"Software Engineer\""));
    }

    #[test]
    fn test_tsv_empty() {
        let processor = TsvProcessor;
        let content = b"name\tage\n";
        let result = processor
            .process(content, &PathBuf::from("test.tsv"))
            .unwrap();

        assert!(result.contains("Headers: name, age"));
        assert!(result.contains("(No data rows found)"));
    }
}

// ============================================================================
// JSONL Processor Tests
// ============================================================================

mod jsonl_tests {
    use super::*;

    #[test]
    fn test_jsonl_with_multiple_lines() {
        let processor = JsonLinesProcessor;
        let content = b"{\"id\":1,\"name\":\"Alice\",\"age\":30}\n{\"id\":2,\"name\":\"Bob\",\"age\":25}\n{\"id\":3,\"name\":\"Charlie\",\"age\":35}";
        let result = processor
            .process(content, &PathBuf::from("test.jsonl"))
            .unwrap();

        assert!(result.contains("JSONL Schema"));
        assert!(
            result.contains("Fields: id, name, age")
                || result.contains("Fields: name, id, age")
                || result.contains("Fields: age, id, name")
        );
        assert!(result.contains("Sample: {\"id\":1,\"name\":\"Alice\",\"age\":30}"));
        assert!(result.contains("[2 more lines omitted]"));
    }

    #[test]
    fn test_jsonl_single_line() {
        let processor = JsonLinesProcessor;
        let content = b"{\"user\":\"john\",\"action\":\"login\"}";
        let result = processor
            .process(content, &PathBuf::from("test.jsonl"))
            .unwrap();

        assert!(result.contains("JSONL Schema"));
        assert!(result.contains("user") && result.contains("action"));
        assert!(result.contains("Sample: {\"user\":\"john\",\"action\":\"login\"}"));
        assert!(!result.contains("more lines omitted"));
    }

    #[test]
    fn test_jsonl_with_nested_objects() {
        let processor = JsonLinesProcessor;
        let content = b"{\"id\":1,\"user\":{\"name\":\"Alice\",\"email\":\"alice@example.com\"}}\n{\"id\":2,\"user\":{\"name\":\"Bob\",\"email\":\"bob@example.com\"}}";
        let result = processor
            .process(content, &PathBuf::from("test.jsonl"))
            .unwrap();

        assert!(result.contains("JSONL Schema"));
        assert!(result.contains("id") && result.contains("user"));
    }

    #[test]
    fn test_jsonl_empty_file() {
        let processor = JsonLinesProcessor;
        let content = b"";
        let result = processor.process(content, &PathBuf::from("test.jsonl"));

        assert!(result.is_err());
    }

    #[test]
    fn test_jsonl_invalid_json() {
        let processor = JsonLinesProcessor;
        let content = b"not a valid json\nanother line";
        let result = processor.process(content, &PathBuf::from("test.jsonl"));

        assert!(result.is_err());
    }

    #[test]
    fn test_jsonl_with_fallback() {
        let processor = JsonLinesProcessor;
        let content = b"invalid json content";
        let result = processor
            .process_with_fallback(content, &PathBuf::from("test.jsonl"))
            .unwrap();

        // Should fallback to raw text
        assert!(result.contains("invalid json content"));
    }
}

