/// Creates a simple directory structure without git
#[fixture]
fn simple_dir_structure() -> TempDir {
    let dir = tempdir().expect("Failed to create temp dir");

    let files = vec![
        ("file1.txt", "Content 1"),
        ("subdir/file2.txt", "Content 2"),
        ("subdir/nested/file3.txt", "Content 3"),
    ];

